export function ensureCampaign(s){
 if(!s.campaign||typeof s.campaign!=='object')s.campaign={};const c=s.campaign;
 for(const k of ['events','duels','contracts','awards','news','seenRivals','rewardedRivals','trainingSeen'])if(!Array.isArray(c[k]))c[k]=[];
 for(const [k,v] of Object.entries({revision:2,xp:0,nextEvent:s.week+3,boostUntil:0,boost:0,sound:false,created:s.week}))if(c[k]===undefined)c[k]=v;
 if(!c.initialized){c.initialized=true;if(s.week>0){for(const [id,title,met,xp]of [['release','第一束光',s.models.some(m=>m.published),8],['users','第一千位用户',E.totalUsers(s)>=1000,15],['paid','有人愿意为它付费',E.totalPaid(s)>=100,10],['funding','跑道延长了',s.holders.length>0,12]])if(met){c.awards.push({id,title,date:E.dateOf(s),inherited:true});c.xp+=xp;}c.trainingSeen=s.projects.filter(p=>p.type==='train'&&p.status==='done'&&!p.pilot).map(p=>p.id);}c.seenRivals=availableRivals(E.dateOf(s)).map(r=>r.id);pushEvent(s,s.week===0&&s.models.length===1?'kickoff':'invitation');addNews(s,'公司','办公室的灯，又一次亮起来了。','你可以与同期模型较量、接下社区机会，也可以坚持自己的研究路线。');}
 return c;
}
export function addNews(s,tag,title,body,extra={}){const c=s.campaign;c.news.unshift({id:uid(s,'news'),date:E.dateOf(s),tag,title,body,...extra});c.news=c.news.slice(0,35);}
export function pushEvent(s,kind,params={}){ensureNoRecursion(s);const existing=s.campaign.events.find(e=>e.kind===kind&&e.status==='pending');if(existing)return existing;const e={id:uid(s,'event'),kind,params,status:'pending',created:s.week};s.campaign.events.unshift(e);s.campaign.events=s.campaign.events.slice(0,40);return e;}
function ensureNoRecursion(s){if(!s.campaign)s.campaign={events:[],news:[]};}
export function eventInfo(s,e){const p=e.params||{};const model=s.models.find(m=>m.id===p.model)||s.models.at(-1);const rival=RIVALS.find(r=>r.id===p.rival);const defs={
 kickoff:{person:'researcher',tag:'创业的第一天',title:'我们要做的第一件事？',body:'白板还是空的，服务器刚接通电。社区愿意提供一批整理过的材料，我们有机会用较少的预算同时探索几种能力。方向由你决定。',choices:[['duo','代码与故事，两边都试','¥18万 · 获取代码和角色材料，带入可修改方案'],['foundation','先打下自己的基础','¥25万 · 获取书籍和数学材料，从头设计模型'],['release','把原型交给第一批用户','零发布预算 · 打开发布会设置，先听反馈']]},
 invitation:{person:'community',tag:'社区来信',title:'有人想把你和 '+nearestRival(s,model).name+' 放在一起测。',body:'“大公司有大公司的榜，我们也想看看新团队能做出什么。”社区测评频道发来邀请。原型也能上场；输赢之外，还能知道不同用户为什么选你。',choices:[['arena','接受邀请，看看对手','进入模型竞技场 · 自由选择参赛模型'],['opportunities','先看看社区需要什么','打开机会板，可同时接下多项合作'],['research','我们再准备一轮实验','回到实验室 · 保留邀请，之后随时参赛']]},
 capacity:{person:'engineer',tag:'机房提醒',title:'门外排起了队，服务器也一样。',body:'免费体验带来了人，也带来了请求。现在部分用户开始等待。如果继续放大推广，我们需要先决定怎样承接这些流量。',choices:[['rent','再租 4 张 GPU','每周租赁增加 ¥0.72万 · 立即增加服务容量'],['quota','暂时把免费次数减半','所有公开产品免费次数减半 · 降低服务压力'],['wait','先观察一周','维持当前策略 · 排队可能继续影响口碑']]},
 data:{person:'researcher',tag:'材料合作',title:'这批材料，值得花时间吗？',body:'合作方整理了一份数学解答；也可以把同样的预算用在已有材料的抽查和去重。数量之外，数据的质量会影响下一轮实验。',choices:[['buy','拿下数学材料','¥12万 · 数学材料入库，已有时进一步整理'],['clean','整理我们手里的材料','¥6万 · 已有材料各改善一轮，最多两轮'],['skip','先不增加投入','不花钱 · 保留当前数据方案']]},
 stability:{person:'engineer',tag:'训练监控',title:'曲线抖了一下。继续，还是检查？',body:'监控捕捉到训练波动，还不能确定是噪声还是稳定性问题。追加检查有助于减少风险，但会占用一点进度。',choices:[['inspect','追加一次检查','¥5万 · 下调中断风险，回退少量未保存进度'],['pause','先暂停这个项目','保留进度 · 可以继续其他路线'],['continue','维持计划，继续训练','不追加投入 · 保留当前风险']]},
 review:{person:'community',tag:'公开实测',title:'“演示很好看，能把测试过程也放出来吗？”',body:'一位社区测评者希望检查模型在真实任务里的表现。公开接受测试会花一些预算，也可能让更多人理解模型的优点和局限。',choices:[['test','把模型交给实测','¥1万 · 运行评测，公开接受检验'],['ama','先来一场开发者交流','¥4万 · 品牌触达 +800，信任 +3'],['read','先收集具体问题','不花钱 · 保持研发节奏']]},
 rival:{person:'researcher',tag:'行业转折',title:(rival?.name||'新的模型')+' 来了。',body:(rival?.note||'同期竞争正在变化。')+' 大家的讨论已经开始转向它。我们可以立即对照，也可以调整产品，或者继续当前研究。',choices:[['compare','放到同一张桌子上比较','进入竞技场，查看逐项差距与社区盲测'],['price','公开产品降价 15%','降低用户门槛，同时减少每位订阅者收入'],['focus','继续自己的技术路线','保持定价与研发 · 竞争压力仍然存在']]},
 community:{person:'community',tag:'本周机会',title:'用户愿意留下来听你说。',body:'社区想了解这家公司正在做什么。一次交流能扩大触达；一份真实可复现的测试，也能成为接下来传播的起点。',choices:[['ama','开一场社区交流','¥4万 · 信任 +3，触达 +800'],['trial','扩大试用邀请','免费产品额度至少 20 次，补贴上限增加 ¥1万/周'],['quiet','专心做出下一轮成果','维持当前策略 · 不增加支出']]}
 };
 return {...(defs[e.kind]||defs.community),model,rival};
}
export function chooseEvent(s,id,key){ensureCampaign(s);const e=s.campaign.events.find(e=>e.id===id&&e.status==='pending');if(!e)return {error:'这封来信已经处理。'};const info=eventInfo(s,e);if(!info.choices.some(c=>c[0]===key))return {error:'请选择信中的一个选项。'};let cost=0,result={},text='';
 if(e.kind==='kickoff'){
  if(key==='duo'){cost=18;result.preset='both';text='团队把代码与角色材料搬进了仓库。';}
  if(key==='foundation'){cost=25;result.preset='scratch';text='书籍与数学材料已经备好，白板留给你的架构。';}
  if(key==='release'){result.launch=s.models[0].id;text='让第一批用户决定，他们愿意为什么留下。';}
 }else if(e.kind==='invitation'){result.navigate=key==='arena'?'arena':key==='opportunities'?'opportunities':'research';text='下一步，由你安排。';}
 else if(e.kind==='data'){if(key==='buy')cost=12;if(key==='clean')cost=6;text=key==='skip'?'这次先保留预算。':'数据团队开始准备下一轮材料。';}
 else if(e.kind==='stability'){if(key==='inspect')cost=5;text=key==='inspect'?'工程师追加了检查，训练计划已经调整。':key==='pause'?'项目已暂停，其他路线仍可继续。':'监控会继续关注训练。';}
 else if(['community','review'].includes(e.kind)){if(key==='ama')cost=4;if(key==='test')cost=1;text=key==='ama'?'交流后，一些人记住了这家公司的名字。':key==='test'?'模型正在接受公开的任务测试。':key==='trial'?'邀请已经发出，请留意下周服务压力。':'团队继续收集问题，保持当前节奏。';}
 else if(e.kind==='capacity')text=key==='rent'?'新算力已经接通。':key==='quota'?'免费次数已调整，先让现有用户顺畅使用。':'工程师会继续盯着队列。';
 else if(e.kind==='rival'){if(key==='compare'){result.navigate='arena';result.rival=e.params.rival;}text=key==='price'?'新的价格已经生效。':'竞争还在继续，我们也一样。';}
 if(s.cash<cost)return {error:'这个决定需要 ¥'+cost+' 万，目前现金不足。'};
 if(!(e.kind==='review'&&key==='test'))s.cash-=cost;
 if(e.kind==='kickoff'&&key==='duo'){s.inventory.code??={clean:0};s.inventory.roleplay??={clean:0};}
 if(e.kind==='kickoff'&&key==='foundation'){s.inventory.books??={clean:0};s.inventory.math??={clean:0};}
 if(e.kind==='data'&&key==='buy'){if(s.inventory.math)s.inventory.math.clean=Math.min(2,s.inventory.math.clean+1);else s.inventory.math={clean:0};}
 if(e.kind==='data'&&key==='clean')Object.values(s.inventory).forEach(d=>d.clean=Math.min(2,d.clean+1));
 if(e.kind==='capacity'&&key==='rent')s.gpus=Math.min(512,s.gpus+4);
 if(e.kind==='capacity'&&key==='quota')s.models.filter(m=>m.published).forEach(m=>m.quota=Math.floor(m.quota/2));
 if(e.kind==='stability'){const p=s.projects.find(p=>p.id===e.params.project&&p.status==='running');if(p&&key==='inspect'){p.estimate.risk*=.45;p.fail=p.fail&&E.random(s)<.35;p.progress=Math.max(p.checkpoint||0,p.progress-.06);}if(p&&key==='pause')p.status='paused';}
 if(key==='ama'){s.reputation=E.clamp(s.reputation+3,0,100);s.reach+=800;}
 if(e.kind==='review'&&key==='test'){const r=E.benchmark(s,info.model.id);if(r.error)return r;result.report=r.result;s.reputation=E.clamp(s.reputation+1.5,0,100);}
 if(e.kind==='community'&&key==='trial'){s.models.filter(m=>m.published).forEach(m=>m.quota=Math.max(20,m.quota));s.freeCap+=1;s.reach+=450;}
 if(e.kind==='rival'&&key==='price')s.models.filter(m=>m.published).forEach(m=>m.price=Math.round(m.price*.85));
 e.status='resolved';e.choice=key;e.resolved=s.week;e.outcome=text;s.campaign.xp+=3;E.log(s,info.title,text,'story');return {ok:true,text,...result};
}
export function chapter(s){const c=ensureCampaign(s);if(c.xp>=180)return {number:'04',name:'与前沿同行',subtitle:'你开始影响这个行业的方向。'};if(c.xp>=90)return {number:'03',name:'有人开始追赶你',subtitle:'领先是一时的，路线是你自己的。'};if(c.xp>=35)return {number:'02',name:'被世界看见',subtitle:'第一批用户，第一场真正的较量。'};return {number:'01',name:'无名之辈',subtitle:'先做出一件值得被记住的事。'};}
export function acceptContract(s,id){const c=ensureCampaign(s),def=CONTRACTS.find(t=>t.id===id);if(!def)return {error:'机会不存在。'};if(c.contracts.some(t=>t.id===id))return {error:'这个机会已经接洽过。'};c.contracts.push({id,status:'active',accepted:s.week,deadline:s.week+def.weeks});E.log(s,'接下合作 · '+def.client,def.name+'，期限 '+def.weeks+' 周。','contract');checkContracts(s);return {ok:true};}
export function contractProgress(s,def){const published=s.models.filter(m=>m.published),evaluated=m=>s.benchmarks.some(b=>b.model===m.id);let best=0,model=null;for(const m of published){let score=0;if(def.kind==='code')score=Math.min(1,m.scores[1]/30)*(evaluated(m)?1:.65);if(def.kind==='story')score=Math.min(1,m.scores[3]/35,m.scores[4]/28,(s.cohorts.rp.active||0)/100);if(def.kind==='classroom')score=Math.min(1,m.scores[0]/35,m.scores[2]/30,m.quota/10);if(def.kind==='math')score=Math.min(1,m.scores[2]/45)*(evaluated(m)?1:.65);if(def.kind==='production')score=Math.min(1,m.scores[0]/40,m.scores[1]/38,(s.last.capacity||1)/.75,E.totalUsers(s)/1000);if(score>best){best=score;model=m;}}
 if(def.kind==='duel')best=s.campaign.duels.some(d=>d.winner==='you')?1:0;return {progress:E.clamp(best,0,1),model};}
export function checkContracts(s){for(const t of s.campaign.contracts.filter(t=>t.status==='active')){const def=CONTRACTS.find(d=>d.id===t.id);if(!def)continue;const p=contractProgress(s,def);if(p.progress>=.999){t.status='complete';t.model=p.model?.id;E.log(s,'合作通过验收',def.name+'，可以领取合作款。','success');}else if(s.week>t.deadline){t.status='expired';E.log(s,'合作机会结束',def.client+' 本次未等到交付。研究仍可继续，没有额外罚款。','contract');}}}
export function claimContract(s,id){ensureCampaign(s);const t=s.campaign.contracts.find(t=>t.id===id),def=CONTRACTS.find(d=>d.id===id);if(!t||!def||t.status!=='complete')return {error:'这项合作尚未通过验收，或已经结算。'};t.status='claimed';s.cash+=def.reward;s.campaign.xp+=def.xp;s.influence=E.clamp(s.influence+3,0,100);s.reputation=E.clamp(s.reputation+2,0,100);E.log(s,'合作款到账',def.client+' 支付 ¥'+def.reward+' 万。','success');addNews(s,'合作',def.name,def.client+' 的验收通过。你的技术开始走进具体的用途。');return {ok:true,reward:def.reward};}
export function checkMilestones(s){const c=ensureCampaign(s);const milestones=[
 ['release','第一束光',s.models.some(m=>m.published),6,8],['users','第一千位用户',E.totalUsers(s)>=1000,10,15],['paid','有人愿意为它付费',E.totalPaid(s)>=100,8,10],['funding','跑道延长了',s.holders.length>0,0,12],['win','无名之辈的反击',c.duels.some(d=>d.winner==='you'),10,20],['five','五条不同的可能',s.models.length>=5,12,20],['trust','口碑开始生长',s.reputation>=75,10,20]
 ];const earned=[];for(const [id,title,condition,cash,xp]of milestones){if(condition&&!c.awards.some(a=>a.id===id)){c.awards.push({id,title,date:E.dateOf(s)});s.cash+=cash;c.xp+=xp;earned.push(title);E.log(s,'里程碑 · '+title,(cash?'获得 ¥'+cash+' 万合作支持，':'')+'团队经验 +'+xp+'。','milestone');}}
 for(const p of s.projects.filter(p=>p.type==='train'&&p.status==='done'&&!p.pilot)){if(!c.trainingSeen.includes(p.id)){c.trainingSeen.push(p.id);c.xp+=6;}}
 return earned;
}
export function runDuel(s,ownId,rivalId){ensureCampaign(s);const own=s.models.find(m=>m.id===ownId),rival=availableRivals(E.dateOf(s)).find(r=>r.id===rivalId);if(!own||!rival)return {error:'请选择你的模型与当前时间线已有的对手。'};if(s.cash<2)return {error:'组织一次盲测需要 ¥2 万。'};s.cash-=2;
 const groups=SEGMENTS.map(g=>{const a=indexScore(own,g.id),b=indexScore(rival,g.id);const gap=(a-b)/10+((own.speed||60)-(rival.speed||60))*.004;const probability=E.clamp(.5+Math.tanh(gap/2)*.44,.06,.94);let votes=0;for(let i=0;i<100;i++)if(E.random(s)<probability)votes++;return {segment:g.id,you:votes,rival:100-votes,a,b};});const votes=E.sum(groups.map(g=>g.you)),winner=votes>250?'you':votes<250?'rival':'tie';const battle={id:uid(s,'duel'),date:E.dateOf(s),week:s.week,model:own.id,rival:rival.id,ownName:own.name,rivalName:rival.name,groups,votes,winner,swapped:E.random(s)>.5};
 s.campaign.duels.unshift(battle);s.campaign.duels=s.campaign.duels.slice(0,40);const rewarded=winner==='you'&&!s.campaign.rewardedRivals.includes(rival.id);if(rewarded){s.campaign.rewardedRivals.push(rival.id);s.influence=E.clamp(s.influence+3,0,100);s.reach+=1200;s.campaign.xp+=12;battle.reward=8;s.cash+=8;}else battle.reward=0;s.reputation=E.clamp(s.reputation+(winner==='you'?1.2:.4),0,100);
 const headline=winner==='you'?own.name+' 在社区盲测中领先 '+rival.name:winner==='tie'?own.name+' 与 '+rival.name+' 战成平手':rival.name+' 获得更多社区选票';E.log(s,'社区盲测揭晓',headline+'。你的模型获得 '+votes+'/500 票。','duel');addNews(s,'社区盲测',headline,'五类用户各投 100 票。优势与短板已经出现在结果里。',{duel:battle.id});
 for(const g of groups){const seg=SEGMENTS.find(t=>t.id===g.segment);if(g.you>=50)E.addPost(s,g.segment,seg.name+'测评组',own.name+' 对比 '+rival.name+'：我们这组 '+g.you+' 人选了前者。'+(g.segment==='rp'?'文风和对话一致性很重要。':g.segment==='dev'?'同样的任务，代码和修改质量更有说服力。':'我们更关心具体任务里的表现。'),'positive',{source:'simulated',duel:battle.id});}
 checkContracts(s);checkMilestones(s);return {battle};
}
export function roundSamples(s,battle){const own=s.models.find(m=>m.id===battle.model),rival=RIVALS.find(r=>r.id===battle.rival);const task=[
 {title:'代码 · 保留顺序去重',question:'输入 [3, 1, 3, 2]，去重并保留首次出现的顺序。',index:1,correct:'def unique(xs):\n    return list(dict.fromkeys(xs))\n\n输出：[3, 1, 2]',weak:'return sorted(set(xs))\n\n输出：[1, 2, 3]\n排序改变了原始顺序。'},
 {title:'推理 · 涨跌之后',question:'商品原价 100 元，先涨价 20%，再降价 20%。现在多少钱？',index:2,correct:'100 × 1.2 × 0.8 = 96 元。\n两次百分比的基数不同，最终比原价低 4 元。',weak:'涨幅和降幅相同，认为最后回到 100 元。\n这一步忽略了基数变化。'},
 {title:'AIRP · 保持角色设定',question:'角色一直害怕海水。几轮对话后，同行的人邀请他下海。',index:4,correct:'他停在潮线外，捏紧了袖口。\n“我就在这里等你，好吗？”他勉强笑了笑，目光仍避着浪。',weak:'他兴奋地跳进海里，招手叫你跟上。\n这一轮丢失了先前的恐水设定。'}
 ];return task.map((t,i)=>{const strongA=own.scores[t.index]>=rival.scores[t.index];const a=strongA?t.correct:t.weak,b=strongA?t.weak:t.correct;return {...t,a:battle.swapped?b:a,b:battle.swapped?a:b};});}
function extraFeedback(s){const published=s.models.filter(m=>m.published);if(!published.length)return;const rivals=availableRivals(E.dateOf(s));const g=SEGMENTS[Math.floor(E.random(s)*SEGMENTS.length)],own=published.slice().sort((a,b)=>indexScore(b,g.id)-indexScore(a,g.id))[0],rival=rivals.slice().sort((a,b)=>Math.abs(indexScore(a,g.id)-indexScore(own,g.id))-Math.abs(indexScore(b,g.id)-indexScore(own,g.id)))[0];if(!rival)return;const diff=indexScore(own,g.id)-indexScore(rival,g.id);const texts={dev:diff>=0?'在代码这块，我开始觉得 '+own.name+' 比 '+rival.name+' 更合我的工作习惯。':'和 '+rival.name+' 对照之后，'+own.name+' 的代码修改还需要再打磨。不过小模型的速度确实不错。',rp:diff>=0?'榜首未必是我的首选。'+own.name+' 的文风比 '+rival.name+' 更对我的胃口，长聊再测一阵。':'试了 '+own.name+'，也试了 '+rival.name+'。我更在意人设能否持续，更新时请别突然换一种说话方式。',science:'我把 '+own.name+' 和 '+rival.name+' 放到同一组题上。'+(diff>=0?'前者的表现已经值得继续检查。':'目前后者更稳，希望下一版能补上关键推导。'),everyday:own.quota>0?own.name+' 每天有 '+own.quota+' 次免费，我能先体验再决定订阅。也会和 '+rival.name+' 比比日常问题。':'我会同时看 '+own.name+' 和 '+rival.name+'。能省下时间、价格合适，才会一直用。',business:'已经把 '+own.name+' 与 '+rival.name+' 放进内部对照清单。效果之外，稳定性和预算同样重要。'};E.addPost(s,g.id,['递归的猫','纸上的星','今天喝茶','长夜旅人','工作流观察'][SEGMENTS.indexOf(g)]+' / 对照体验',texts[g.id],diff>=0?'positive':'neutral');}
export function advance(s){ensureCampaign(s);const before={history:new Set(s.seenHistory),projects:new Set(s.projects.filter(p=>p.status==='done').map(p=>p.id)),users:E.totalUsers(s),cash:s.cash};const r=E.advanceWeek(s);if(r.error)return r;
 finishJobs(s);const c=s.campaign;const released=availableRivals(E.dateOf(s)).filter(t=>!c.seenRivals.includes(t.id));for(const rival of released){c.seenRivals.push(rival.id);addNews(s,'对手动态',rival.name+' 正式进入这段历史',rival.note,{rival:rival.id});if(released.length<3)pushEvent(s,'rival',{rival:rival.id});}
 if(s.week>=c.nextEvent){let kind='community',params={};const training=s.projects.find(p=>p.type==='train'&&p.status==='running');if(training&&E.random(s)<.45){kind='stability';params.project=training.id;}else if(s.last.capacity<.68&&s.models.some(m=>m.published))kind='capacity';else if(s.week%3===0)kind='data';else if(s.models.some(m=>m.published))kind='review';pushEvent(s,kind,params);c.nextEvent=s.week+3+Math.floor(E.random(s)*3);}
 checkContracts(s);const earned=checkMilestones(s);extraFeedback(s);const completed=s.projects.filter(p=>p.status==='done'&&!before.projects.has(p.id));c.lastWeek={week:s.week,newUsers:E.totalUsers(s)-before.users,cash:s.cash-before.cash,revenue:s.last.revenue,expense:s.last.expense,released:released.map(t=>t.id),completed:completed.map(p=>p.id),milestones:earned};return {ok:true,report:c.lastWeek};
}
export function published(s,id){ensureCampaign(s);const m=s.models.find(m=>m.id===id);if(!m)return;addNews(s,'你的发布',m.name+'，现在见。','订阅 ¥'+m.price+'/月，每人每天 '+m.quota+' 次免费体验。',{model:id});checkMilestones(s);checkContracts(s);}
export function nearestRival(s,m,group='overall'){return availableRivals(E.dateOf(s)).slice().sort((a,b)=>Math.abs(indexScore(a,group)-indexScore(m,group))-Math.abs(indexScore(b,group)-indexScore(m,group)))[0];}

const IMPORT_SPECS={
 'gpt-j':{params:6,active:6,context:2048},bloom:{params:176,active:176,context:2048},llama2:{params:70,active:70,context:4096,attention:'gqa'},mistral:{params:7,active:7,context:8192,attention:'gqa'},mixtral:{params:46.7,active:12.9,context:32768,arch:'moe',attention:'gqa'},deepseekv3:{params:671,active:37,context:128000,arch:'moe',attention:'mla'},deepseekr1:{params:671,active:37,context:128000,arch:'moe',attention:'mla'},deepseekv4:{params:284,active:13,context:1000000,arch:'moe',attention:'mla'}
};
export function publicBases(s){return availableRivals(E.dateOf(s)).filter(r=>IMPORT_SPECS[r.id]).map(r=>({...r,spec:IMPORT_SPECS[r.id],cost:Math.round(12+Math.sqrt(IMPORT_SPECS[r.id].params)*4),weeks:IMPORT_SPECS[r.id].params>100?4:2}));}
export function importBase(s,id){ensureCampaign(s);const base=publicBases(s).find(x=>x.id===id);if(!base)return {error:'当前时间线还不能引入这个公开基座。'};if(s.models.some(m=>m.sourceRival===id)||s.projects.some(p=>p.type==='integration'&&p.payload?.rival===id))return {error:'这个基座已经引入或正在集成。'};if(s.cash<base.cost)return {error:'集成预算不足，需要 ¥'+base.cost+' 万。'};s.cash-=base.cost;s.projects.push({id:uid(s,'integration'),type:'integration',name:'公开基座接入 · '+base.name,progress:0,status:'running',weeks:base.weeks,gpus:1,cost:base.cost,payload:{rival:id},estimate:{params:base.spec.params,arch:base.spec.arch||'dense'}});E.log(s,'接入公开基座',base.name+' 开始集成，预计 '+base.weeks+' 周。','research');return {ok:true};}
export function collectionEstimate(s,opts){const tokens=E.clamp(Number(opts.tokens)||1,.1,50),source=['community','expert','teacher'].includes(opts.source)?opts.source:'community';const cost=Math.round((source==='expert'?12:source==='teacher'?7:4)+Math.sqrt(tokens)*(source==='expert'?9:source==='teacher'?5:3));const weeks=Math.max(2,Math.ceil((source==='expert'?4:3)+Math.log2(tokens+1)/2-Math.max(0,s.team.data-1)*.25));return {tokens,source,cost,weeks};}
export function commissionData(s,opts){ensureCampaign(s);if(!String(opts.name||'').trim())return {error:'给这份材料起一个名字。'};const e=collectionEstimate(s,opts);if(s.cash<e.cost)return {error:'本次采集需要 ¥'+e.cost+' 万，现金不足。'};const allowed=['general','code','math','creative','memory'];const focus=Array.isArray(opts.focus)?opts.focus.filter(x=>allowed.includes(x)):['general'];if(!focus.length)return {error:'请至少选择一个采集主题。'};const weights=allowed.map(x=>focus.includes(x)?1/focus.length:0);const teacher=s.models.slice().sort((a,b)=>E.sum(b.scores)-E.sum(a.scores))[0];const quality=E.clamp((e.source==='expert'?85:e.source==='teacher'?56+E.sum(teacher.scores)/5*.25:62)+(E.random(s)-.5)*10,40,95);const payload={id:uid(s,'customdata'),name:String(opts.name).trim().slice(0,45),tag:opts.format==='preference'?'偏好 / 定制':opts.format==='dialogue'?'任务 / 对话':'领域文本',source:e.source==='expert'?'专家委托':e.source==='teacher'?'自有模型生成与筛选':'社区贡献与整理',tokens:e.tokens,quality,noise:E.clamp((100-quality)/170,.03,.35),cost:0,weights,sample:'围绕'+focus.map(x=>({general:'知识与日常',code:'编程任务',math:'数学推导',creative:'创作与人物',memory:'长对话一致性'}[x])).join('、')+'收集的'+(opts.format==='preference'?'回答偏好与纠错材料':opts.format==='dialogue'?'任务示范与多轮对话':'文本、解答与相关材料')+'。',date:E.dateOf(s),custom:true};s.cash-=e.cost;s.projects.push({id:uid(s,'collection'),type:'collection',name:'材料采集 · '+payload.name,status:'running',progress:0,weeks:e.weeks,gpus:1,cost:e.cost,payload,estimate:{arch:'data',params:0}});E.log(s,'材料采集已开始',payload.name+' · '+e.weeks+' 周 · ¥'+e.cost+' 万。','data');return {ok:true};}
function finishJobs(s){s.customDatasets??=[];for(const p of s.projects.filter(p=>['integration','collection'].includes(p.type)&&p.status==='done'&&!p.delivered)){
 if(p.type==='collection'){s.customDatasets.push(p.payload);s.inventory[p.payload.id]={clean:0};p.delivered=true;addNews(s,'材料入库',p.payload.name+' 已经准备好了。','新材料可在任何训练项目中自由配比。');E.log(s,'定制材料已入库',p.payload.name+'，可在下一轮训练中使用。','success');}
 else {const r=RIVALS.find(x=>x.id===p.payload.rival),spec=IMPORT_SPECS[r.id];const m={id:uid(s,'model'),name:s.company+' · '+r.name+' 适配',params:spec.params,activeParams:spec.active,arch:spec.arch||'dense',attention:spec.attention||'mha',context:spec.context,scores:r.scores.slice(),quality:78,trained:s.week,mode:'continue',speed:r.speed,unit:.00000014*Math.sqrt(spec.active+1),status:'ready',published:false,price:69,quota:20,targets:SEGMENTS.map(g=>g.id),users:0,paid:0,results:[],parent:null,sourceRival:r.id};s.models.push(m);p.delivered=true;if(spec.attention==='mla')s.tech.mla=true;if(spec.attention==='gqa')s.tech.gqa=true;if(spec.arch==='moe')s.tech.moe=true;addNews(s,'基座接入',r.name+' 已进入你的实验室。','可以继续训练、微调或蒸馏出自己的产品。');E.log(s,'公开基座已就绪',m.name+'，保留原始来源，可以开始自己的迭代。','success');}
 }}
