 {id:'developer-week',name:'开发者开放周',group:'dev',cost:9,effect:.5,weeks:4,desc:'邀请开发者把真实代码任务带来，集中扩大技术社区触达。'},
 {id:'story-night',name:'长夜故事会',group:'rp',cost:8,effect:.55,weeks:4,desc:'让创作者尝试角色对话，观察长聊、文风与续费。'},
 {id:'research-club',name:'研究者问题挑战',group:'science',cost:11,effect:.6,weeks:5,desc:'围绕数学和专业问题讨论，以可检查的结果争取信任。'},
 {id:'open-week',name:'人人都能试试',group:'everyday',cost:12,effect:.5,weeks:3,desc:'面向普通用户扩大体验活动，免费补贴与服务容量仍需单独安排。'}
