export function startPromotion(s,id){ensureCampaign(s);const def=PROMOTIONS.find(p=>p.id===id);if(!def)return {error:'活动不存在。'};if(s.trends.some(t=>t.promotion===id&&t.until>=s.week))return {error:'这场活动正在进行。'};if(s.cash<def.cost)return {error:'活动预算不足。'};s.cash-=def.cost;s.trends.push({id:uid(s,'promotion'),promotion:id,name:def.name,segment:def.group,effect:def.effect,until:s.week+def.weeks});s.reach+=def.cost*130;E.log(s,'主题活动开始',def.name+' · '+def.weeks+' 周。体验与容量会决定用户是否留下。','trend');addNews(s,'社区活动',def.name+'，邀请已经发出。',def.desc);return {ok:true};}
